	"log"
)

func CreatePrivateKey() (string, error) {
	// Generate a new RSA private key with error handling
	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return "", fmt.Errorf("failed to generate RSA key: %v", err)
	}

	// Marshal the private key into DER format
	der, err := x509.MarshalPKCS1PrivateKey(privateKey)
	if err != nil {
		return "", fmt.Errorf("failed to marshal private key: %v", err)
	}

	// Wrap the DER data in a PEM block
	pemBlock := &pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: der,
	}

	// Encode the PEM block into a string
	pemData := pem.EncodeToMemory(pemBlock)
	if pemData == nil {
		return "", fmt.Errorf("failed to encode PEM block")
	}

	return string(pemData), nil
}

func main() {
	key, err := CreatePrivateKey()
	if err != nil {
		log.Fatalf("Error creating private key: %v", err)
	}
	fmt.Println("Generated Private Key (PEM):")
	fmt.Println(key)
}

